    colors = set(v for row in body for v in row) - {bg, 8}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if body[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)

        if r0 == h - 3:
            horizontal.append(r0 - thick)
        elif c0 == 0 and r0 > 0:
            horizontal.append(r0 + (r1 - r0 + 1) // 2)
            if color == 2:
                vertical.append(c1 + 1)
        elif c1 == w - 1:
            if color != 3:
                vertical.append(c0 - thick)
        elif r0 == 0 and color != 3:
            horizontal.append(r1 + 1)

